import assert from 'node:assert/strict';
import { callTool, listTools } from './server.mjs';

// --- listTools ---
test('listTools returns text_transform', async () => {
  const tools = await listTools();
  assert.equal(tools.length, 1);
  assert.equal(tools[0].name, 'text_transform');
  assert.equal(tools[0].inputSchema.required.length, 2);
  assert.deepStrictEqual(tools[0].inputSchema.required, ['text', 'mode']);
  assert.strictEqual(tools[0].inputSchema.additionalProperties, false);
});

// --- uppercase ---
test('uppercase basic', async () => {
  const r = await callTool('text_transform', { text: 'hello world', mode: 'uppercase' });
  assert.equal(r.content[0].text, 'HELLO WORLD');
});

test('uppercase with trim (default)', async () => {
  const r = await callTool('text_transform', { text: '  hello  ', mode: 'uppercase' });
  assert.equal(r.content[0].text, 'HELLO');
});

test('uppercase with trim false', async () => {
  const r = await callTool('text_transform', { text: '  hello  ', mode: 'uppercase', trim: false });
  assert.equal(r.content[0].text, '  HELLO  ');
});

// --- lowercase ---
test('lowercase basic', async () => {
  const r = await callTool('text_transform', { text: 'HELLO WORLD', mode: 'lowercase' });
  assert.equal(r.content[0].text, 'hello world');
});

test('lowercase with trim (default)', async () => {
  const r = await callTool('text_transform', { text: '  HELLO  ', mode: 'lowercase' });
  assert.equal(r.content[0].text, 'hello');
});

test('lowercase with trim false', async () => {
  const r = await callTool('text_transform', { text: '  HELLO  ', mode: 'lowercase', trim: false });
  assert.equal(r.content[0].text, '  hello  ');
});

// --- slug ---
test('slug basic', async () => {
  const r = await callTool('text_transform', { text: ' Hello, MCP! ', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-mcp');
});

test('slug with multiple spaces and special chars', async () => {
  const r = await callTool('text_transform', { text: 'Foo!!! Bar---Baz___Qux', mode: 'slug' });
  assert.equal(r.content[0].text, 'foo-bar-baz-qux');
});

test('slug with leading and trailing hyphens', async () => {
  const r = await callTool('text_transform', { text: '--hello world--', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-world');
});

test('slug with numbers', async () => {
  const r = await callTool('text_transform', { text: 'Product 123 Test', mode: 'slug' });
  assert.equal(r.content[0].text, 'product-123-test');
});

test('slug empty string', async () => {
  const r = await callTool('text_transform', { text: '   ', mode: 'slug' });
  assert.equal(r.content[0].text, '');
});

// --- invalid mode ---
test('invalid mode', async () => {
  await assert.rejects(
    () => callTool('text_transform', { text: 'hello', mode: 'capitalize' }),
    /Invalid mode/
  );
});

// --- unknown tool ---
test('unknown tool', async () => {
  await assert.rejects(
    () => callTool('unknown_tool', {}),
    /Unknown tool/
  );
});

// --- missing required field ---
test('missing text field', async () => {
  await assert.rejects(
    () => callTool('text_transform', { mode: 'uppercase' }),
    /text must be a string/
  );
});

test('missing mode field', async () => {
  await assert.rejects(
    () => callTool('text_transform', { text: 'hello' }),
    /Invalid mode/
  );
});
